package com.projexa.coaching.academics.entity;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="academic_years") public class AcademicYear { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false) private String name; @Column(nullable=false) private LocalDate startDate; @Column(nullable=false) private LocalDate endDate; private boolean isCurrent; private String status="ACTIVE"; public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public void setTenantId(UUID v){tenantId=v;} public String getName(){return name;} public void setName(String v){name=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public boolean isCurrent(){return isCurrent;} public void setCurrent(boolean v){isCurrent=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }